const select = function eligibleIssues({ issues }) {
  const escape = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const notifications = [];
  issues.forEach((issue, sourceIndex) => {
    if (issue.pull_request) return;
    if (!Number.isInteger(issue.comments) || issue.comments < 0) throw new Error('GitHub returned an invalid comment count');
    if (issue.comments >= 5) return;
    if (typeof issue.title !== 'string' || typeof issue.html_url !== 'string') throw new Error('GitHub returned an issue without its title or URL');
    const url = new URL(issue.html_url);
    if (!['http:', 'https:'].includes(url.protocol)) throw new Error('GitHub returned an invalid issue URL');
    const text = 'New Issue:  ' + escape(issue.title) + ' <a href="' + escape(url.href) + '">Link</a>';
    if (text.length > 4096) throw new Error('The issue alert exceeds Telegram’s message limit');
    notifications.push({ text, sourceIndex });
  });
  return { notifications, count: notifications.length };
}

return select({issues:$input.all().map(item=>item.json)}).notifications.map(({text,sourceIndex})=>({json:{text},pairedItem:{item:sourceIndex}}));
